css:
.sl-hero-abstract {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 75vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-hero-abstract .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-abstract .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-abstract .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-abstract .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-abstract .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-abstract .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-abstract .sl-btn-primary:hover,
.sl-hero-abstract .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-abstract .sl-btn-outline-primary {
  background-color: transparent;
  border: 1px solid var(--smartlearn-primary);
  color: var(--smartlearn-primary);
}
.sl-hero-abstract .sl-btn-outline-primary:hover,
.sl-hero-abstract .sl-btn-outline-primary:focus-visible {
  background-color: var(--smartlearn-btn-bg);
  border-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-abstract .sl-blob-title {
  letter-spacing: -0.04em;
}
.sl-hero-abstract .sl-tracking-wide {
  letter-spacing: 0.1em;
}
.sl-hero-abstract .sl-blob-mask-container {
  max-width: 550px;
}
.sl-hero-abstract .sl-blob-img {
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: 40% 60% 70% 30% / 40% 50% 60% 50%;
  border: 2px solid var(--smartlearn-card-border);
}
.sl-hero-abstract .sl-blob-bg {
  border-radius: 40% 60% 70% 30% / 40% 50% 60% 50%;
  pointer-events: none;
  z-index: 1;
}
.sl-hero-abstract .sl-blob-accent {
  top: -10%;
  inset-inline-end: 8%;
  width: min(380px, 75vw);
  height: min(380px, 75vw);
  background-color: color-mix(in srgb, var(--smartlearn-primary) 18%, transparent);
}
.sl-hero-abstract .sl-blob-secondary {
  bottom: -15%;
  inset-inline-start: 0;
  width: min(280px, 60vw);
  height: min(280px, 60vw);
  background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
}
.sl-hero-abstract .sl-wobbly-badge {
  bottom: 12%;
  inset-inline-end: 4%;
  z-index: 3;
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-abstract .sl-blob-bg,
  .sl-hero-abstract .sl-blob-img {
    animation: sl-hero-abstract-morph 10s ease-in-out infinite;
  }
  .sl-hero-abstract .sl-wobbly-badge {
    animation: sl-hero-abstract-wobble 4s ease-in-out infinite;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-abstract .sl-blob-bg,
  .sl-hero-abstract .sl-blob-img,
  .sl-hero-abstract .sl-wobbly-badge {
    animation: none;
  }
}
@keyframes sl-hero-abstract-morph {
  0%, 100% { border-radius: 40% 60% 70% 30% / 40% 50% 60% 50%; }
  34% { border-radius: 70% 30% 50% 50% / 30% 30% 70% 70%; }
  67% { border-radius: 60% 40% 35% 65% / 55% 65% 35% 45%; }
}
@keyframes sl-hero-abstract-wobble {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-8px) rotate(2deg); }
}
